import{z as s,x as A,o as t,c as p,q as n,j as B,D as e,d as i,s as o,S as r,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"产能规划与瓶颈","description":"","frontmatter":{"title":"产能规划与瓶颈","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/capacity-planning-bottleneck.md","filePath":"litho/capacity-planning-bottleneck.md","lastUpdated":1791413859000}'),d={name:"litho/capacity-planning-bottleneck.md"};function c(h,a,m,f,b,D){const l=A("Mermaid");return t(),p("div",null,[a[2]||(a[2]=n('<h1 id="产能规划与瓶颈" tabindex="-1">产能规划与瓶颈 <a class="header-anchor" href="#产能规划与瓶颈" aria-label="Permalink to &quot;产能规划与瓶颈&quot;">​</a></h1><div class="epigraph"><p>厂的月产能由最慢的那类约束机台决定；EUV、光化掩模检验和 e-beam 检测常常比浸没扫描机更先成为瓶颈。</p><footer>—— 对照 fab capacity planning 与约束理论在光刻区的应用通称</footer></div><p><a href="/litho/tool-price-depreciation">上一课</a>给出小时成本。缺口是台数。本课钉产能规划与瓶颈。把扫描机采购放进整厂资本开支，留给<a href="/litho/fab-capex">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>需求：晶圆数 × 每片 EUV 层过机 × 1/有效 wph × 1/可用性 ≈ EUV 台数。浸没同理但层数更多。瓶颈可能在：EUV、轨道、刻蚀、掩模写入、AIMS、e-beam 检测、计量。加一台非瓶颈机不增加产出。多重图形把浸没与刻蚀同时变成瓶颈对。</p><p><span class="marginnote">数字实例：月产 5 万片、每片 8 层 EUV 过机、有效 150 片/小时、可用性 80%——需求机时 = 50000×8÷(150×0.8) ≈ 3333 小时/月；一台每月约 720 小时（可用性已含在需求机时里，不重复扣），所以仅 EUV 就要 5 台起步。Mix 一变，这个数马上重算。</span></p><p>缺口是<strong>约束识别</strong>，不是买最贵的机。把产能当「有几台 EUV」，会忽略掩模厂与检测。</p><h3 id="mix-是一等变量" tabindex="-1">Mix 是一等变量 <a class="header-anchor" href="#mix-是一等变量" aria-label="Permalink to &quot;Mix 是一等变量&quot;">​</a></h3><p>产品组合改 EUV 层数与开口率（刻蚀负荷），瓶颈会移动。规划必须用 mix 场景，不能用单一英雄产品。</p><p><span class="marginnote">重工是对瓶颈的隐性需求。高重工率等于少买了几台扫描机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>建资源表：各机类小时需求 vs 供给。缓冲：维护、新品学习、掩模延迟。与交叉课：迁一层到 EUV 是把需求从浸没/刻蚀挪到 EUV/掩模。与学习曲线：爬坡期检测需求峰值。</p><p><span class="marginnote">术语翻译：「WIP」就是还在线上、没完工的晶圆堆。WIP 越多，每片在厂时间越长，被搬运和触碰的机会越多，二次缺陷与返工跟着涨——所以「控制队列」本身就是产能管理的一部分，不只是买机器。</span></p>',13)),(t(),B(r,null,{default:e(()=>[o(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E5%88%97%E5%87%BA%20Mix%20%E5%9C%BA%E6%99%AF%22%5D%20--%3E%20RT%5B%22%E5%BB%BA%E8%B5%84%E6%BA%90%E8%A1%A8%EF%BC%9A%E5%90%84%E6%9C%BA%E7%B1%BB%E9%9C%80%E6%B1%82%20vs%20%E4%BE%9B%E7%BB%99%22%5D%0A%20%20RT%20--%3E%20Q%7B%22%E5%93%AA%E7%B1%BB%E6%9C%BA%E5%8F%B0%E5%88%A9%E7%94%A8%E7%8E%87%E9%A1%B6%E5%88%B0%E4%B8%8A%E9%99%90%EF%BC%9F%22%7D%0A%20%20Q%20--%20%22%E6%98%AF%22%20--%3E%20BN%5B%22%E8%AF%A5%E6%9C%BA%E7%B1%BB%E6%98%AF%E7%93%B6%E9%A2%88%EF%BC%9A%E5%8A%A0%E6%9C%BA%2F%E5%A4%96%E5%8D%8F%2F%E9%87%8D%E6%8E%92%E5%B1%82%22%5D%0A%20%20Q%20--%20%22%E5%90%A6%22%20--%3E%20NB%5B%22%E9%9D%9E%E7%93%B6%E9%A2%88%EF%BC%9A%E5%88%A9%E7%94%A8%E7%8E%87%E5%86%8D%E9%AB%98%E4%B9%9F%E5%8F%AA%E5%A0%86%20WIP%22%5D%0A%20%20BN%20--%3E%20BUF%5B%22%E7%95%99%E7%BC%93%E5%86%B2%EF%BC%9A%E7%BB%B4%E6%8A%A4%E3%80%81%E7%88%AC%E5%9D%A1%E3%80%81%E6%8E%A9%E6%A8%A1%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20NB%20--%3E%20BUF%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[i("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"约束理论：产出由瓶颈决定，非瓶颈的利用率高只是在堆 WIP。光刻区 WIP 增加周期与二次缺陷机会。因此规划不仅是买机器，还是控制队列。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"直觉类比：瓶颈像四车道里唯一剩下的单车道桥——在桥前后再加车道，车只会更堵在桥头；有效的只有拓宽桥本身（加瓶颈机台）或让一部分车绕行（重排 mix、外协）。非瓶颈机台闲置不是浪费，排队才是。")],-1)),(t(),B(r,null,{default:e(()=>[o(l,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20DEM%5B%22%E6%99%B6%E5%9C%86%20%C3%97%20%E5%B1%82%20%C3%97%20%E8%BF%87%E6%9C%BA%22%5D%20--%3E%20NEED%5B%22%E6%9C%BA%E6%97%B6%E9%9C%80%E6%B1%82%22%5D%0A%20%20NEED%20--%3E%20BN%5B%22%E7%93%B6%E9%A2%88%E8%B5%84%E6%BA%90%22%5D%0A%20%20BN%20--%3E%20OUT%5B%22%E6%9C%88%E4%BA%A7%E5%87%BA%22%5D%0A%20%20REW%5B%22%E9%87%8D%E5%B7%A5%22%5D%20--%3E%20NEED%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测某厂台数。不把理论 wph 当供给。规划不含劳动力细节。</p><p>后课默认：产出由瓶颈机类决定；下一课这些机台的买价如何堆成 fab capex。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>产能由瓶颈资源决定；EUV、掩模检验、e-beam 常入围。</li><li>Mix 与重工移动瓶颈。</li><li>非瓶颈加机只堆 WIP。</li><li>出处：fab capacity 与约束理论通称。</li></ul>',5))])}const x=s(d,[["render",c]]);export{C as __pageData,x as default};
